/bin/bash -lc "python - <<'PY'
import numpy as np
A=np.load('source_pixels.npz')['rgb'].astype(int)
for mode in ['prev','zero']:
 print('\\n',mode)
 for t in range(1,96):
  ref=A[t-1] if mode=='prev' else A[0]
  d=np.max(abs(A[t]-ref),axis=2)
  for th in ([10,30,60] if t in [1,2,3,5,10,15,20,30,40,50,60,70,80,90,95] else []):
   y,x=np.where(d>th)
   print(f't{t:02} th{th} n{len(x):4}', ('box '+str((x.min(),y.min(),x.max(),y.max())) if len(x) else ''), end=' | ')
  if t in [1,2,3,5,10,15,20,30,40,50,60,70,80,90,95]: print()
PY"
